import{_ as a,c as s,o as i,ae as t}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"Confidentialité et données","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy.md","filePath":"fr/guide/privacy.md","lastUpdated":1795170900000}'),r={name:"fr/guide/privacy.md"};function o(n,e,l,u,c,d){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="confidentialite-et-donnees" tabindex="-1">Confidentialité et données <a class="header-anchor" href="#confidentialite-et-donnees" aria-label="Permalink to &quot;Confidentialité et données&quot;">​</a></h1><p>Ce qui reste sur votre Mac et quand le réseau est nécessaire.</p><h2 id="enregistre-localement" tabindex="-1">Enregistré localement <a class="header-anchor" href="#enregistre-localement" aria-label="Permalink to &quot;Enregistré localement&quot;">​</a></h2><p>Historique, favoris, onglets ouverts, téléchargements et cookies sont conservés sur votre Mac. Pas de compte, pas de synchronisation cloud. Une fenêtre privée (⌘⇧N) ne laisse ni historique ni session.</p><h2 id="quand-le-reseau-est-utilise" tabindex="-1">Quand le réseau est utilisé <a class="header-anchor" href="#quand-le-reseau-est-utilise" aria-label="Permalink to &quot;Quand le réseau est utilisé&quot;">​</a></h2><ul><li>Pour charger les sites que vous visitez, évidemment.</li><li>Pour actualiser un abonnement de blocage d&#39;annonces, s&#39;il est actif. Si la mise à jour échoue, les règles enregistrées continuent de s&#39;appliquer.</li><li>Pour télécharger un script ou un fichier que vous avez demandé.</li></ul><h2 id="vos-autorisations" tabindex="-1">Vos autorisations <a class="header-anchor" href="#vos-autorisations" aria-label="Permalink to &quot;Vos autorisations&quot;">​</a></h2><p>L&#39;accès à la caméra et au micro est mémorisé par site. La localisation et les notifications sont gérées par macOS. Les fenêtres surgissantes sont limitées aux sites autorisés.</p><h2 id="fichiers-sur-le-disque" tabindex="-1">Fichiers sur le disque <a class="header-anchor" href="#fichiers-sur-le-disque" aria-label="Permalink to &quot;Fichiers sur le disque&quot;">​</a></h2><p>Persim ne lit que les fichiers choisis dans le dialogue système ou auxquels vous avez donné accès explicitement. Vous pouvez vérifier et révoquer ces autorisations dans les réglages.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions de confidentialité : <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>.</p>',12)])])}const p=a(r,[["render",o]]);export{m as __pageData,p as default};
